(()=>{
  if(!location.pathname.startsWith('/photographer'))return;
  let allowed=false,initialized=false,source=null,sample=null,outline=[],manual=false,outputUrl='';
  const css=`.pbSubjectLauncher{width:calc(50% - 8px);min-height:180px;margin:16px 0;border:1px solid #cbd8f4;border-radius:18px;background:#f7f9ff;color:#244da9;padding:20px;font:inherit;text-align:center;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:9px;cursor:pointer}.pbSubjectLauncher span{font-size:30px}.pbSubjectLauncher b{font-size:18px}.pbSubjectLauncher small{color:#687892}.pbSubjectCard{margin:20px 0;padding:22px;border:1px solid #c8d7f5;border-radius:20px;background:#fff;direction:rtl;color:#24314f}.pbSubjectCard[hidden]{display:none!important}.pbSubjectCard h2{margin:0 0 8px;font-size:22px}.pbSubjectCard p{line-height:1.85;color:#62718b}.pbSubjectGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.pbSubjectCard label{display:grid;gap:9px;font-weight:700}.pbSubjectCard input[type=file]{display:block;width:100%;padding:12px;border:1px solid #d9e2ef;border-radius:12px}.pbSubjectPreview{position:relative;margin-top:10px;display:inline-block;max-width:100%;background:#eef3fa}.pbSubjectPreview img{display:block;max-width:100%;max-height:440px}.pbSubjectPreview svg{position:absolute;inset:0;width:100%;height:100%;touch-action:none;cursor:crosshair}.pbSubjectActions{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}.pbSubjectActions button,.pbSubjectDownload{padding:10px 16px;border:0;border-radius:10px;background:#315efb;color:white;font:inherit;cursor:pointer}.pbSubjectActions button.secondary{background:#edf2ff;color:#3156a7}.pbSubjectActions button:disabled{opacity:.45;cursor:not-allowed}.pbSubjectResult img{display:block;max-width:min(100%,360px);max-height:500px}.pbSubjectStatus{min-height:24px;color:#3156a7}.pbSubjectStatus.error{color:#b13535}@media(max-width:700px){.pbSubjectLauncher{width:100%}.pbSubjectGrid{grid-template-columns:1fr}}`;
  const style=document.createElement('style');style.textContent=css;document.head.append(style);
  const esc=s=>String(s||'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[ch]));
  const read=file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});
  async function api(path,body){const r=await fetch(path,{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json','x-photobridge-portal':'photographer'},body:JSON.stringify(body)});if(!r.ok){let x={};try{x=await r.json()}catch{}throw Error(x.detail||x.error||`HTTP ${r.status}`)}return r}
  function message(value,error=false){const el=document.querySelector('#pbSubjectStatus');if(el){el.textContent=value;el.classList.toggle('error',error)}}
  function draw(){const svg=document.querySelector('#pbSubjectSvg');if(!svg)return;svg.innerHTML=outline.length?`<polygon points="${outline.map(([x,y])=>`${x},${y}`).join(' ')}" fill="rgba(64,124,255,.18)" stroke="#2455ee" stroke-width="3" vector-effect="non-scaling-stroke"/>${outline.map(([x,y],i)=>`<circle data-point="${i}" cx="${x}" cy="${y}" r="8" fill="#fff" stroke="#2455ee" stroke-width="3" vector-effect="non-scaling-stroke"/>`).join('')}`:'';document.querySelector('#pbSubjectPointCount').textContent=outline.length?`${outline.length} نقطهٔ مرز سوژه`:'مرز سوژه هنوز مشخص نشده';document.querySelector('#pbSubjectGenerate').disabled=!source||!sample||outline.length<8}
  function mount(){if(!allowed)return;const parent=document.querySelector('.photographerAiToolsWorkspace'),grid=parent?.querySelector('.aiServiceActionGrid');if(!grid)return;
    let launcher=parent.querySelector('#pbSubjectLauncher');if(!launcher){launcher=document.createElement('button');launcher.type='button';launcher.id='pbSubjectLauncher';launcher.className='pbSubjectLauncher';launcher.innerHTML='<span aria-hidden="true">✦</span><b>جایگذاری سوژه در بک نمونه</b><small>عکس اصلی + عکس نمونه · خروجی ۳۰×۴۰</small>';grid.after(launcher)}
    launcher.onclick=()=>{const editor=parent.querySelector('#pbSubjectCard');if(!editor)return;editor.hidden=!editor.hidden;if(!editor.hidden)editor.scrollIntoView({behavior:'smooth',block:'start'})};
    if(parent.querySelector('#pbSubjectCard'))return;
    const section=document.createElement('section');section.id='pbSubjectCard';section.className='pbSubjectCard';section.innerHTML=`<h2>جایگذاری سوژه در بک نمونه · آزمایشی</h2><p>عکس اصلی و عکس نمونه را انتخاب کن. هوش مصنوعی فقط صحنهٔ بدون آدم را می‌سازد؛ پیکسل‌های چهره، بدن و لباس از عکس اصلی روی آن قرار می‌گیرند. مرز آبی را قبل از خروجی بررسی کن.</p><div class="pbSubjectGrid"><label>عکس اصلی<input id="pbSubjectOriginal" type="file" accept="image/jpeg,image/png,image/webp"></label><label>عکس نمونهٔ بک<input id="pbSubjectSample" type="file" accept="image/jpeg,image/png,image/webp"></label></div><div class="pbSubjectActions"><button id="pbSubjectAuto" class="secondary" disabled>تشخیص خودکار کل سوژه</button><button id="pbSubjectManual" class="secondary" disabled>ترسیم مرز دستی</button><button id="pbSubjectUndo" class="secondary" disabled>حذف نقطهٔ آخر</button></div><div id="pbSubjectPointCount">مرز سوژه هنوز مشخص نشده</div><div class="pbSubjectPreview"><img id="pbSubjectSourceImage" alt="عکس اصلی"><svg id="pbSubjectSvg" viewBox="0 0 1000 1000" preserveAspectRatio="none" aria-label="مرز قابل ویرایش سوژه"></svg></div><p>در حالت دستی دور تمام بدن و موها نقطه بگذار؛ نقطه‌های موجود را می‌توانی بگیری و جابه‌جا کنی. حداقل ۸ نقطه لازم است.</p><div class="pbSubjectActions"><button id="pbSubjectGenerate" disabled>ساخت خروجی ۳۰×۴۰ · ۳۰۰ DPI</button></div><p id="pbSubjectStatus" class="pbSubjectStatus" role="status"></p><div id="pbSubjectResult" class="pbSubjectResult"></div>`;
    const heading=parent.querySelector('.photographerAiOtherToolsHead');if(heading){const title=heading.querySelector('h2');if(title)title.textContent='پنج ابزار تکمیلی در یک بخش';const summary=heading.querySelector('p');if(summary)summary.textContent='ترمیم، رنگی‌سازی، افزایش کیفیت، گسترش تصویر و جایگذاری سوژه در بک نمونه.'}launcher.after(section);section.hidden=true;const $=id=>section.querySelector('#'+id);
    $('pbSubjectOriginal').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>15_000_000){message('حجم عکس اصلی باید کمتر از ۱۵ مگابایت باشد.',true);return}source=await read(f);$('pbSubjectSourceImage').src=source;outline=[];manual=false;$('pbSubjectAuto').disabled=false;$('pbSubjectManual').disabled=false;$('pbSubjectUndo').disabled=true;draw();message('عکس اصلی بارگذاری شد؛ تشخیص خودکار را بزن.')};
    $('pbSubjectSample').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>15_000_000){message('حجم نمونه باید کمتر از ۱۵ مگابایت باشد.',true);return}sample=await read(f);draw();message('عکس نمونه بارگذاری شد.')};
    $('pbSubjectAuto').onclick=async()=>{if(!source)return;message('مرز کل سوژه در حال تشخیص است…');$('pbSubjectAuto').disabled=true;try{const r=await api('/api/customer/ai-subject-composite/outline',{originalBase64:source});outline=(await r.json()).outline;manual=false;draw();$('pbSubjectUndo').disabled=false;message('مرز را بررسی کن؛ نقطه‌ها را می‌توانی جابه‌جا کنی.')}catch(e){message('تشخیص خودکار کامل نشد: '+e.message+'؛ از ترسیم دستی استفاده کن.',true)}finally{$('pbSubjectAuto').disabled=false}};
    $('pbSubjectManual').onclick=()=>{outline=[];manual=true;draw();$('pbSubjectUndo').disabled=false;message('روی دورِ تمام شخص نقطه بگذار؛ نقطهٔ اول و آخر خودکار به هم وصل می‌شوند.')};
    $('pbSubjectUndo').onclick=()=>{outline.pop();draw()};
    const svg=$('pbSubjectSvg');let dragging=-1;const point=e=>{const rect=svg.getBoundingClientRect();return [Math.max(0,Math.min(1000,Math.round((e.clientX-rect.left)/rect.width*1000))),Math.max(0,Math.min(1000,Math.round((e.clientY-rect.top)/rect.height*1000)))]};
    svg.onpointerdown=e=>{if(!source)return;const index=Number(e.target?.dataset?.point);if(Number.isInteger(index)&&e.target?.dataset?.point!==undefined){dragging=index;svg.setPointerCapture(e.pointerId)}else if(manual){outline.push(point(e));draw()}};
    svg.onpointermove=e=>{if(dragging<0)return;outline[dragging]=point(e);draw()};svg.onpointerup=()=>{dragging=-1};svg.onpointercancel=()=>{dragging=-1};
    $('pbSubjectGenerate').onclick=async()=>{if(!source||!sample||outline.length<8)return;const button=$('pbSubjectGenerate');button.disabled=true;message('بک در حال ساخت و سوژهٔ اصلی در حال ترکیب است؛ ممکن است چند دقیقه طول بکشد…');try{const r=await api('/api/customer/ai-subject-composite/render',{originalBase64:source,sampleBase64:sample,outline});const blob=await r.blob();if(outputUrl)URL.revokeObjectURL(outputUrl);outputUrl=URL.createObjectURL(blob);$('pbSubjectResult').innerHTML=`<img src="${esc(outputUrl)}" alt="پیش‌نمایش خروجی"><a class="pbSubjectDownload" href="${esc(outputUrl)}" download="PhotoBridge-30x40-300dpi.png">دانلود PNG چاپی</a>`;const scale=Number(r.headers.get('x-photobridge-subject-scale')||1);message(scale===1?'خروجی آماده است؛ سوژه با اندازهٔ پیکسل اصلی ترکیب شد.':'خروجی آماده است؛ سوژهٔ بزرگ‌تر از کادر برای جا شدن کوچک شد.')}catch(e){message('ساخت خروجی انجام نشد: '+e.message,true)}finally{button.disabled=false}};
  }
  async function authorize(){if(initialized)return;initialized=true;try{const r=await fetch('/api/auth/me',{credentials:'same-origin',headers:{'x-photobridge-portal':'photographer'}});const me=await r.json();if(me?.user?.labRole!=='customer'){initialized=false;setTimeout(authorize,3000);return}const probe=await fetch('/api/customer/ai-subject-composite/access',{credentials:'same-origin',headers:{'x-photobridge-portal':'photographer'}});allowed=probe.ok;if(allowed){mount();new MutationObserver(mount).observe(document.body,{childList:true,subtree:true})}}catch{initialized=false;setTimeout(authorize,3000)}}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',authorize,{once:true});else authorize();
})();
